mapper.select:
select main.* from ( select T.*, (select count(1) from ${dbUserBjts}doc_fileinfo f where ((f.nsrdzdah = T.nsrdzdah and f.busitype = 'sbxx' and f.busikey = T.sbid) or (f.nsrsbh = T.nsrsbh and f.busitype = 'qyscba')) and f.filetype = '1') as fjsl from (select hz.id as sbid, hz.nsrdzdah, dab.swjg_dm as swjgdm, swjg.swjg_jc as swjgmc, nvl(dab.shxyno, dab.nsrsbh) as nsrsbh, dab.qyhgdm, dab.nsrmc, dab.qylx_dm as qylx, dab.qylx_dm as qylxZh, hz.sbywb_dm as sbywb, hz.sbywb_dm as sbywbZh, hz.sssq, hz.sbpc, hz.sbrq, hz.sbzt_dm as sbzt, hz.sbzt_dm as sbztZh, hz.fkxx, (case when uuid like 'DYCK%' then '单一窗口' else '出口退税' end) as lyZh, dab.cpcode from ${dbUserBjts}sb_sbxx_hz hz, ${dbUserBjts}gs_dj_cktmsdab dab, ${dbUserBjts}dm_swjg swjg where hz.nsrdzdah = dab.nsrdzdah and dab.swjg_dm = swjg.swjg_dm) T
) main
order by main.${orderSql}
order by main.sbid desc

select id,nsrdzdah,filename,fmcode,title,filesize,rootpath, filepath,note
from ${dbUserBjts}doc_fileinfo
where id = #{fileId,jdbcType=BIGINT}


            and nsrdzdah = #{nsrdzdah,jdbcType=BIGINT}


            and nsrsbh = #{nsrsbh}
